"use client";

import { memo, useId, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { Heart, Menu, X } from "lucide-react";
import { cn } from "cn";
import { GitHubDark } from "@ridemountainpig/svgl-react";
import { samplePageLinks } from "../lib/navigation.shared";
import { Avatar } from "../components/avatar";
import { Badge } from "../components/badge";
import { Banner } from "../components/banner";
import { Button } from "../components/button";

interface NavbarProps extends ComponentProps<"header"> {
  brand?: string;
  logo?: ReactNode;
  homeHref?: string;
  links?: {
    label: string;
    href: string;
  }[];
  activeHref?: string;
  announcement?: string;
  badge?: string;
  supportHref?: string;
  githubHref?: string;
  account?: {
    name: string;
    src?: string;
    href: string;
  };
}

export const Navbar = memo(function Navbar({
  brand = "Hangry UI",
  logo,
  homeHref = "#home",
  links = samplePageLinks,
  activeHref,
  announcement,
  badge = "",
  supportHref = "#sponsor",
  githubHref = "#github",
  account,
  className,
  children,
  ...props
}: NavbarProps = {}) {
  const [open, setOpen] = useState(false);
  const menuId = useId();
  const toggle = useRef<HTMLButtonElement>(null);
  function closeMenu() {
    setOpen(false);
    toggle.current?.focus();
  }
  return (
    <header
      {...props}
      data-slot="navbar"
      data-layout="centered"
      className={cn(
        "@container w-full text-foreground",
        "border border-border bg-background",
        className,
      )}
    >
      {announcement && (
        <Banner
          message={announcement}
          dismissible={false}
          className="border-0 border-b border-border"
        />
      )}
      <div
        className={cn(
          "grid grid-cols-[1fr_auto] items-center gap-4 px-5 py-4",
          "@4xl:grid-cols-[1fr_auto_1fr]",
        )}
      >
        <a
          href={homeHref}
          className="flex w-fit items-center gap-2 text-lg font-semibold focus-visible:outline-2 focus-visible:outline-ring"
        >
          {logo}
          <span>{brand}</span>
          {badge && <Badge variant="neutral">{badge}</Badge>}
        </a>
        <nav
          aria-label="Primary navigation"
          className={cn("hidden items-center gap-6 @4xl:flex", "justify-center")}
        >
          {links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              aria-current={activeHref === link.href ? "page" : undefined}
              className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring aria-[current=page]:text-foreground"
            >
              {link.label}
            </a>
          ))}
        </nav>
        <div className="flex items-center justify-end gap-2">
          {supportHref && (
            <a
              href={supportHref}
              aria-label="Support the project"
              className="inline-flex size-9 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"
            >
              <Heart size={18} aria-hidden="true" />
            </a>
          )}
          {githubHref && (
            <a
              href={githubHref}
              aria-label="GitHub repository"
              className="inline-flex size-9 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"
            >
              <GitHubDark className="invert dark:invert-0" width={18} height={18} aria-hidden="true" />
            </a>
          )}
          {account && (
            <a
              href={account.href}
              aria-label={`${account.name}'s account`}
              className="focus-visible:outline-2 focus-visible:outline-ring"
            >
              <Avatar name={account.name} src={account.src} size={32} />
            </a>
          )}
          <Button
            ref={toggle}
            variant="ghost"
            className="min-h-9 px-2 @4xl:hidden"
            aria-label={open ? "Close navigation" : "Open navigation"}
            aria-expanded={open}
            aria-controls={menuId}
            onClick={() => setOpen(!open)}
          >
            {open ? <X size={18} aria-hidden="true" /> : <Menu size={18} aria-hidden="true" />}
          </Button>
        </div>
      </div>
      <nav
        id={menuId}
        aria-label="Mobile navigation"
        hidden={!open}
        className="border-t border-border px-5 py-3 @4xl:hidden"
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.preventDefault();
            closeMenu();
          }
        }}
      >
        {links.map((link) => (
          <a
            key={link.href}
            href={link.href}
            aria-current={activeHref === link.href ? "page" : undefined}
            onClick={() => setOpen(false)}
            className="block px-2 py-3 text-sm text-muted-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring aria-[current=page]:text-foreground"
          >
            {link.label}
          </a>
        ))}
      </nav>
      {children}
    </header>
  );
});

"use client";

import { useState } from "react";

interface AvatarProps {
  src?: string;
  name?: string;
  size?: number;
  className?: string;
}

export function Avatar({ src, name = "Alex Morgan", size = 48, className = "" }: AvatarProps = {}) {
  const [failedSrc, setFailedSrc] = useState<string>();
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase();
  // Registry consumers can use any React framework and image URL.
  /* eslint-disable @next/next/no-img-element */
  return (
    <span
      role="img"
      aria-label={name}
      style={{ width: size, height: size }}
      className={`inline-flex shrink-0 items-center justify-center overflow-hidden border border-border bg-emerald-400/15 text-sm font-semibold text-emerald-800 dark:text-emerald-300 ${className}`}
    >
      {src && failedSrc !== src ? (
        <img
          src={src}
          alt=""
          width={size}
          height={size}
          onError={() => setFailedSrc(src)}
          className="h-full w-full object-cover"
        />
      ) : (
        initials || "?"
      )}
    </span>
  );
}

"use client";

import { memo, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, type HTMLMotionProps } from "motion/react";
import {
  CircleCheck,
  CircleDashed,
  CircleX,
  Clock3,
  SearchCheck,
  Send,
  TriangleAlert,
} from "lucide-react";

interface BadgeProps extends Omit<HTMLMotionProps<"span">, "children"> {
  children?: ReactNode;
  variant?:
    | "pending"
    | "in-progress"
    | "submitted"
    | "in-review"
    | "success"
    | "failed"
    | "expired"
    | "neutral"
    | "info"
    | "warning"
    | "error"
    | "blue"
    | "purple"
    | "pink"
    | "teal"
    | "orange";
}

const statuses = {
  pending: { label: "Pending", icon: TriangleAlert },
  "in-progress": { label: "In progress", icon: CircleDashed },
  submitted: { label: "Submitted", icon: Send },
  "in-review": { label: "In review", icon: SearchCheck },
  success: { label: "Success", icon: CircleCheck },
  failed: { label: "Failed", icon: CircleX },
  expired: { label: "Expired", icon: Clock3 },
};

const styles = {
  pending: "bg-orange-500/10 text-orange-700 dark:text-orange-400",
  "in-progress": "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  submitted: "bg-violet-500/10 text-violet-700 dark:text-violet-400",
  "in-review": "bg-yellow-500/10 text-yellow-700 dark:text-yellow-400",
  success: "bg-green-500/10 text-green-700 dark:text-green-400",
  failed: "bg-red-500/10 text-red-700 dark:text-red-400",
  expired: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  neutral: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  info: "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  warning: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  error: "bg-red-500/10 text-red-700 dark:text-red-400",
  blue: "bg-blue-500/10 text-blue-700 dark:text-blue-400",
  purple: "bg-purple-500/10 text-purple-700 dark:text-purple-400",
  pink: "bg-pink-500/10 text-pink-700 dark:text-pink-400",
  teal: "bg-teal-500/10 text-teal-700 dark:text-teal-400",
  orange: "bg-orange-500/10 text-orange-700 dark:text-orange-400",
};

export const Badge = memo(function Badge({
  children,
  variant = "success",
  className = "",
  ...props
}: BadgeProps = {}) {
  const status = variant in statuses ? statuses[variant as keyof typeof statuses] : undefined;
  const Icon = status?.icon;
  const reducedMotion = useReducedMotion();

  return (
    <motion.span
      initial={reducedMotion ? false : { opacity: 0, y: 20 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.5 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.03 }}
      transition={{ duration: reducedMotion ? 0 : 0.35, ease: "easeOut" }}
      className={`inline-flex items-center gap-2 rounded-lg surface-raised surface-status px-3 py-2 typography-label ${styles[variant]} ${className}`}
      {...props}
    >
      {Icon && <Icon aria-hidden="true" className="size-[1.15em] shrink-0" strokeWidth={2.25} />}
      {children ?? status?.label ?? "New release"}
    </motion.span>
  );
});

"use client";

import { memo, useState, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion } from "motion/react";
import { CircleCheck, CircleX, Info, TriangleAlert } from "lucide-react";

interface BannerProps {
  variant?: "neutral" | "info" | "success" | "warning" | "error";
  children?: ReactNode;
  message?: string;
  description?: string;
  dismissible?: boolean;
  className?: string;
}

const statusStyles = {
  neutral: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  info: "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  success: "bg-green-500/10 text-green-700 dark:text-green-400",
  warning: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  error: "bg-red-500/10 text-red-700 dark:text-red-400",
};

const statusIcons = {
  neutral: Info,
  info: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleX,
};

export const Banner = memo(function Banner({
  variant = "info",
  children,
  message = "A little update. A lot of possibilities. Explore what's new.",
  description,
  dismissible = true,
  className = "",
}: BannerProps = {}) {
  const Icon = statusIcons[variant];
  const reducedMotion = useReducedMotion();
  const [dismissed, setDismissed] = useState(false);

  if (dismissed) return null;

  return (
    <motion.div
      role={variant === "error" ? "alert" : "status"}
      initial={reducedMotion ? false : { opacity: 0, y: 10 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.2 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.005 }}
      transition={{ duration: reducedMotion ? 0 : 0.2, ease: "easeOut" }}
      className={`flex items-start gap-4 rounded-xl surface-raised surface-status px-5 py-4 text-base leading-7 ${statusStyles[variant]} ${className}`}
    >
      {Icon && <Icon aria-hidden="true" className="mt-0.5 size-6 shrink-0" strokeWidth={2} />}
      <div className="min-w-0 flex-1">
        <div className="font-semibold">{children ?? message}</div>
        {description && <p className="mt-1 text-sm leading-6 opacity-90">{description}</p>}
      </div>
      {dismissible && (
        <button
          type="button"
          aria-label="Dismiss banner"
          onClick={() => setDismissed(true)}
          className="flex size-9 shrink-0 items-center justify-center hover:bg-black/10 focus-visible:outline-2 focus-visible:outline-current"
        >
          <span aria-hidden="true">×</span>
        </button>
      )}
    </motion.div>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});

